begin;
create table if not exists public.alertcheckin_staff_map(ac_site_name text not null, staff_name text not null, candidate_id uuid not null references public.candidates(id) on delete cascade, created_at timestamptz not null default now(), primary key(ac_site_name,staff_name));
grant select on public.alertcheckin_staff_map to authenticated; grant all on public.alertcheckin_staff_map to service_role;
alter table public.alertcheckin_staff_map enable row level security;
do $$begin if not exists(select 1 from pg_policies where tablename='alertcheckin_staff_map') then create policy "Admins read ac staff map" on public.alertcheckin_staff_map for select to authenticated using ((select public.is_admin_user())); end if; end$$;
